    def configuration_manage(self, **kwargs):
        """
        *Description:* \n
        This keyword is used to perform configuration management.

        *Steps Followed* \n
          a. Creates plan and adds/edits moc parameter to plan \n
          b. Uploads configuration data \n
          c. Provisions the plan

        *Parameters:* \n

        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |
        | operation | Mandatory | Create or Edit or Delete or Deconfigure. Valid on EMS interface only | delta_files  |
        |  |  | Operation argument is valid only for EMS. It will become dummy when the keyword is called over netact |  |
        |  |  | interface |  |
        | bts_moc_id | primary bts moc id | bts moc id |  |
        | alias | default | Name of execution context. | |
        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | plan_name | iv_fw_plan |  Specifies a plan name. Uses an existing plan with given name, else a new plan |  |
        |  |  | is created. For NOM, this "plan_name" will be chosen to select parameters from "configure_manage" |  |
        |  |  | section testline_config | `config reference` |
        | config | Mandatory | JSON file with list of dict. Either config file or moc_and_params_dict are mandatory |  |
        |  |  |  | `config reference` |
        | delete_plan | True | Deletes plan at the end of operation | delta_files |
        | should_provision | True | If True provisions the configuration after plan creation |  |
        | timeout | 7200 | Operation timeout. |  |
        | provisioning_operation | activate | Specifies a provisioning operation (activate/ |  |
        |  |  | preactivate/activate_preactivated_plan). |  |
        | ignore_errors | False | If True, shows warnings instead of raising errors when operation fails |  |
        | skip_autocorrection | False | If True, skips delta autocorrection for Netact |  |
        | parameters | None | (dict) - Parameters not parameterized at the level of method but allowed by CLI |  |
        |  |  | ex:{'-lteContentInUse': False, '-sranBtsContentInUse': Falsel} |  |
        |  |  | applicable only for activate_preactivated_plan operation. |  |
        | verbose | True | (bool) - If True, returns more detailed output from executed operation. |  |
        |  |  | applicable only for activate_preactivated_plan operation. |  |
        | schedule | None | (str) - prepare_schedule method should be used to obtain correct value |  |
        |  |  | applicable only for activate_preactivated_plan operation. |  |

        *Returns*:
        None

        *Raises*:

       """
        return Commissioning().configuration_manage(**kwargs)

