    def netact_pm_counters_start(self, **kwargs):
        """
        *Description:* \n
        This keyword starts to collect counters.

        *Parameters:* \n

        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |
        | pm_interval | 15 | In Minutes, 30 and 60 shall be supported on request  | |
        | alias | default | Name of the execution context | |
        | bts_dut | bts | section name in testline config | `testline_config` |
        | interval_start_extra_wait | 0 | Extra wait time to start the interval |  |
        | interval_end_extra_wait | -60 | Additional Wait time Past the Interval |  |

        *Returns:* Counter Start and End Time

        *Raises*:
        """
        counters_obj = Counters()
        alias = kwargs.get("alias", "default")
        self.store.add(counters_obj, alias=alias)
        return counters_obj.start_counters(**kwargs)

    def netact_pm_counters_stop_and_verify(self, **kwargs):
        """
        *Description:* \n
         This keyword stops counter collection and verifies the counter according to the given analysis

        *Parameters:* \n
        *Common*
        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |
        | pm_interval | 15 | In Minutes, 30 and 60 shall be supported on request  | |
        | bts_dut | bts | section in testline config |  |
        | analysis | Mandatory | analysis name as given in counters analysis resource file | `counters analysis ref` |
        | counter_analysis_file | Mandatory | analysis file name | `counters analysis ref` |
        | pm_interval | 15 | In minutes. The PM interval type  | 15 mins is supported at the moment |  |
        | alias | default | Name of the execution context |  |

        """
        alias = kwargs.get("alias", "default")
        counters_obj = self.store.get(alias=alias)
        result = None
        try:
            result = counters_obj.stop_and_verify_counters(**kwargs)
        except Exception as e:
            raise Exception(e)
        finally:
            self.store.remove(alias=alias)
            return result

