    def generate_reports(self, **kwargs):

        """
        Generate SWAM reports and wait for generation to complete.
        *Keyword: * Generate Reports
        *Parameters:*\n
            | *Name* | *Default Value* | *Comments* | *Config Ref* |
            | module_name | Mandatory | Expected module name='moduleName1' to generate reports. |  |
            | detailed | True | If False - only general information about the modules will be returned. |  |
            | recheck_interval | 20 | Interval between checking report generation task status. |  |
            | max_retries | 20 | Maximum number of rechecks |  |
            | trigger | 'GENERATE_REPORT_ON_DEMAND' | Allowed values: GENERATE_REPORT_TASK, |  |
            |  |  | LICENSE_MANAGER_NOTIFICATION, HARDLOCK_SCHEDULER_TASK, GENERATE_REPORT_REMOTE_SERVICE, |  |
            |  |  | GRACE_PERIOD_CAPACITY_CHANGED, HASH_FAIL, GENERATE_REPORT_ON_DEMAND. |  |
            | day | 0 | (int|string|datetime.date) - Day or day indicating the end of period that has to be covered |  |
            |  |  | in report. Allowed values: 0 for today, -1 for yesterday and so on (the NetAct time zone is |  |
            |  |  | included) or YYYY-mm-dd e.g. 2020-02-20. |  |
            | alias | 'default' | netact instance name. |  |


        *Returns:*\n
            reports generation status

        *Return type:*\n
            dict

        *Examples:*\n
        | Generate Reports | detailed=True | module_name=module_name | recheck_interval=20 | max_retries=20 |
        |  | trigger='GENERATE_REPORT_ON_DEMAND' | day=0 | alias=alias |

        """

        return SWAM().generate_reports(**kwargs)

